async function boot(){startVersionPolling();const session=await api('/api/me');if(!session.user){login();return;}document.body.classList.remove('login-ready');let marker='';try{marker=sessionStorage.getItem(AUTH_TAB_KEY)||'';}catch{}identity=session.user;csrf=session.csrf;if(marker!==identity.id){try{await api('/api/auth/logout',{});}catch{}identity=null;csrf='';login();return;}window.schoolUser=identity;window.schoolStageDurations=session.stageDurations;startIdleSession();if(identity.role!=='student'){await teacher();return;}startBroadcastPolling();if(session.ready){const posttest=await api('/api/posttest');if(posttest.active){let announced=false;try{announced=sessionStorage.getItem(posttestAnnouncementKey(posttest))==='1';}catch{}if(posttest.phase!=='certificate'&&!announced){showPosttestTransition(posttest);return;}await studentPosttest(posttest);return;}await studentEntry(session.group);}else await studentTests();}
boot().catch(error=>{screen.hidden=false;document.querySelector('.app').hidden=true;screen.replaceChildren(header('暂时无法连接','请确认服务已启动后重试'),message(error.message,true),button('重新连接',()=>location.reload()));});
